def progress_response(record, version):
    if version == 'v1':
        return {'status_code': 200, 'body': {'lesson': record['lesson'], 'done': record['done']}}
    if version == 'v2':
        state = 'completed' if record['done'] else 'started'
        return {'status_code': 200, 'body': {'lesson': record['lesson'], 'status': state}}
    return {'status_code': 400, 'body': {'error': 'unsupported_version'}}

record = {'lesson': 'files', 'done': False}
v1 = progress_response(record, 'v1')
v2 = progress_response(record, 'v2')
assert v1['body'] == {'lesson': 'files', 'done': False}
assert isinstance(v1['body']['done'], bool)
assert v2['body'] == {'lesson': 'files', 'status': 'started'}
assert progress_response(record, 'v3')['status_code'] == 400
print(v1, v2)

